// ──────────────────────────────────────────────
// Types
// ──────────────────────────────────────────────

export interface DiagnosticResult {
  name: string;
  status: "pass" | "fail" | "warn" | "skip";
  message: string;
  detail?: string;
  duration_ms?: number;
}

export interface DiagnosticReport {
  timestamp: string;
  environment: string;
  summary: { pass: number; fail: number; warn: number; skip: number; total: number };
  results: DiagnosticResult[];
}

// ──────────────────────────────────────────────
// Expected environment variables per provider
// ──────────────────────────────────────────────

const ENV_VARS = {
  REQUIRED: [] as string[], // none strictly required — app degrades gracefully
  RECOMMENDED: {
    MONGODB_URI: "MongoDB Atlas connection string (needed for persistence)",
    OPENROUTER_API_KEY: "OpenRouter free-tier API key (multi-model vision/text)",
    GEMINI_API_KEY: "Google Gemini API key (direct vision fallback)",
    FREETHEAI_API_KEY: "FreeTheAi API key (free text provider)",
    GROQ_API_KEY: "Groq API key (free text provider)",
    SAMBANOVA_API_KEY: "SambaNova API key (free text provider)",
    HF_TOKEN: "HuggingFace token (free text provider)",
  },
  CONDITIONAL: {
    CLOUDFLARE_API_TOKEN: "Cloudflare API token (needs CLOUDFLARE_ACCOUNT_ID too)",
    CLOUDFLARE_ACCOUNT_ID: "Cloudflare account ID (needs CLOUDFLARE_API_TOKEN too)",
    GITHUB_TOKEN: "GitHub token (needs fine-grained AI inference access)",
  },
} as const;

// ──────────────────────────────────────────────
// Individual checks
// ──────────────────────────────────────────────

function check(label: string, fn: () => Promise<DiagnosticResult>): Promise<DiagnosticResult> {
  const start = Date.now();
  return fn().then((r) => ({ ...r, name: label, duration_ms: Date.now() - start }));
}

/** 1. Environment variable presence check */
async function checkEnvVars(): Promise<DiagnosticResult> {
  const missing: string[] = [];

  for (const [key, desc] of Object.entries(ENV_VARS.RECOMMENDED)) {
    if (!process.env[key]) missing.push(`${key} — ${desc}`);
  }

  // Conditional checks — warn if one is set without the other
  if (process.env.CLOUDFLARE_API_TOKEN && !process.env.CLOUDFLARE_ACCOUNT_ID) {
    missing.push("CLOUDFLARE_ACCOUNT_ID — set when CLOUDFLARE_API_TOKEN is present");
  }
  if (process.env.CLOUDFLARE_ACCOUNT_ID && !process.env.CLOUDFLARE_API_TOKEN) {
    missing.push("CLOUDFLARE_API_TOKEN — set when CLOUDFLARE_ACCOUNT_ID is present");
  }

  const hasAnyAI = ENV_VARS.RECOMMENDED
    ? Object.keys(ENV_VARS.RECOMMENDED).some((k) => process.env[k])
    : false;

  if (missing.length === 0) {
    return {
      name: "env-vars",
      status: "pass",
      message: "All recommended env vars are set",
    };
  }

  // If none of the AI keys are set at all, it's a bigger issue
  if (!hasAnyAI && !process.env.GEMINI_API_KEY) {
    return {
      name: "env-vars",
      status: "warn",
      message: `No AI API keys configured — app will rely entirely on offline Python OCR`,
      detail: missing.join("\n"),
    };
  }

  return {
    name: "env-vars",
    status: "warn",
    message: `${missing.length} recommended env var(s) missing`,
    detail: missing.join("\n"),
  };
}

/** 2. MongoDB connectivity check */
async function checkMongoDB(): Promise<DiagnosticResult> {
  const uri = process.env.MONGODB_URI;
  if (!uri) {
    return {
      name: "mongodb",
      status: "skip",
      message: "MONGODB_URI not set — app works without persistence",
    };
  }

  try {
    const start = Date.now();
    // The db.findById returns null on error, so we try a direct aggregate/count
    const count = await db.count("scans").catch(() => null);
    if (count === null) throw new Error("MongoDB connection failed");

    return {
      name: "mongodb",
      status: "pass",
      message: `Connected to MongoDB (${count} scans in collection)`,
      duration_ms: Date.now() - start,
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    // Detect common Atlas SSL/whitelist errors
    let hint = "";
    if (msg.includes("SSL") || msg.includes("tlsv1") || msg.includes("alert internal error")) {
      hint = " — check Atlas Network Access whitelist (add your current IP)";
    } else if (msg.includes("Authentication failed") || msg.includes("auth failed")) {
      hint = " — check username/password in MONGODB_URI";
    } else if (msg.includes("ENOTFOUND") || msg.includes("EAI_AGAIN")) {
      hint = " — DNS resolution failed, check cluster hostname";
    }

    return {
      name: "mongodb",
      status: "fail",
      message: `Cannot connect to MongoDB${hint}`,
      detail: msg.slice(0, 300),
    };
  }
}

/** 3. Python + Tesseract OCR availability */
async function checkOCRPipeline(): Promise<DiagnosticResult> {
  const pythonPath = `C:\\Users\\maqso\\AppData\\Local\\hermes\\hermes-agent\\venv\\Scripts\\python.exe`;
  const tesseractPath = `C:\\Program Files\\Tesseract-OCR\\tesseract.exe`;

  // Check Tesseract binary
  if (!existsSync(tesseractPath)) {
    return {
      name: "ocr-pipeline",
      status: "fail",
      message: "Tesseract OCR binary not found",
      detail: `Expected at: ${tesseractPath}\nInstall: winget install UB-Mannheim.TesseractOCR`,
    };
  }

  // Check Python binary
  if (!existsSync(pythonPath)) {
    return {
      name: "ocr-pipeline",
      status: "fail",
      message: "Hermes-agent Python venv not found",
      detail: `Expected at: ${pythonPath}\nMake sure hermes-agent is installed`,
    };
  }

  // Quick Python import test
  try {
    const result = execSync(
      `"${pythonPath}" -c "import PIL; import pytesseract; print(PIL.__version__); print(pytesseract.get_tesseract_version())"`,
      { timeout: 15000, maxBuffer: 1024 * 1024 }
    ).toString().trim();

    const lines = result.split("\n");
    return {
      name: "ocr-pipeline",
      status: "pass",
      message: `Python OCR pipeline ready (PIL ${lines[0]}, ${lines[1]})`,
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return {
      name: "ocr-pipeline",
      status: "fail",
      message: "Python OCR pipeline failed import check",
      detail: msg.slice(0, 300),
    };
  }
}

/** 4. Disk & temp directory check */
async function checkDisk(): Promise<DiagnosticResult> {
  const ocrDir = join(tmpdir(), "menulens-ocr");
  try {
    if (!existsSync(ocrDir)) {
      // Creating the dir is part of the check — readable, writable?
      mkdirSync(ocrDir, { recursive: true });
      const testFile = join(ocrDir, ".write-test");
      writeFileSync(testFile, "ok");
      unlinkSync(testFile);
    }

  // Check writeability with an actual write
    accessSync(ocrDir, constants.W_OK | constants.R_OK);

    return {
      name: "disk",
      status: "pass",
      message: `Temp directory writable (${ocrDir})`,
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return {
      name: "disk",
      status: "fail",
      message: "Temp directory not writable — OCR will fail",
      detail: msg.slice(0, 200),
    };
  }
}

/** 5. Port availability check */
async function checkPort(port: number = 3000): Promise<DiagnosticResult> {
  try {
    // Quick check if port is already in use by trying to create a server
    const result = await new Promise<string>((resolve) => {
      const server = createServer();
      server.once("error", (err: NodeJS.ErrnoException) => {
        if (err.code === "EADDRINUSE") resolve(`Port ${port} is in use (${err.message})`);
        else resolve(`Port check error: ${err.message}`);
      });
      server.once("listening", () => {
        server.close();
        resolve("available");
      });
      server.listen(port, "127.0.0.1");
    });

    if (result === "available") {
      return {
        name: "port-3000",
        status: "pass",
        message: `Port ${port} is available`,
      };
    }

    return {
      name: "port-3000",
      status: "warn",
      message: result,
      detail: "Stop the existing process with: taskkill /F /IM node.exe",
    };
  } catch (err) {
    return {
      name: "port-3000",
      status: "skip",
      message: `Could not check port ${port}`,
      detail: err instanceof Error ? err.message : String(err),
    };
  }
}

/** 6. Project dependency check (node_modules sanity) */
async function checkDependencies(): Promise<DiagnosticResult> {
  const pkgPath = join(process.cwd(), "package.json");
  if (!existsSync(pkgPath)) {
    return { name: "dependencies", status: "fail", message: "package.json not found" };
  }

  const pkg = JSON.parse(readFileSync(pkgPath, "utf-8"));
  const modulesPath = join(process.cwd(), "node_modules");

  if (!existsSync(modulesPath)) {
    return { name: "dependencies", status: "fail", message: "node_modules missing — run npm install" };
  }

  // Spot-check a few critical deps
  const criticalDeps = ["next", "react", "mongodb", "pino"];
  const missingDeps: string[] = [];

  for (const dep of criticalDeps) {
    const depPath = join(modulesPath, dep);
    if (!existsSync(depPath)) {
      missingDeps.push(dep);
    }
  }

  if (missingDeps.length > 0) {
    return {
      name: "dependencies",
      status: "fail",
      message: `Missing critical dependencies: ${missingDeps.join(", ")}`,
      detail: "Run: npm install",
    };
  }

  return {
    name: "dependencies",
    status: "pass",
    message: `All critical dependencies found (${Object.keys(pkg.dependencies || {}).length} total)`,
  };
}

/** 7. Check that key page files exist */
async function checkRoutes(): Promise<DiagnosticResult> {
  const srcDir = join(process.cwd(), "src");

  const expectedFiles = [
    "app/page.tsx",
    "app/layout.tsx",
    "app/scan/page.tsx",
    "app/results/[id]/page.tsx",
    "app/api/scan/new/route.ts",
    "app/api/scan/[id]/route.ts",
  ];

  const missing: string[] = [];
  for (const file of expectedFiles) {
    if (!existsSync(join(srcDir, file))) {
      missing.push(file);
    }
  }

  if (missing.length > 0) {
    return {
      name: "routes",
      status: "fail",
      message: `${missing.length} expected route file(s) missing`,
      detail: missing.join("\n"),
    };
  }

  return {
    name: "routes",
    status: "pass",
    message: `${expectedFiles.length} key route files exist`,
  };
}

/** 8. Check that ErrorBoundary component exists (referenced in layout.tsx) */
async function checkErrorBoundary(): Promise<DiagnosticResult> {
  const componentsDir = join(process.cwd(), "src", "components");
  if (!existsSync(componentsDir)) {
    return {
      name: "error-boundary",
      status: "fail",
      message: "src/components/ directory is missing",
      detail: "Layout imports from @/components/ErrorBoundary but directory doesn't exist",
    };
  }

  const ebPath = join(componentsDir, "ErrorBoundary.tsx");
  if (!existsSync(ebPath)) {
    return {
      name: "error-boundary",
      status: "fail",
      message: "ErrorBoundary.tsx is referenced in layout.tsx but does not exist",
      detail: "Path expected: src/components/ErrorBoundary.tsx\nThis will cause a build error if the file is not created.",
    };
  }

  return {
    name: "error-boundary",
    status: "pass",
    message: "ErrorBoundary component exists",
  };
}

// ──────────────────────────────────────────────
// Orchestrator
// ──────────────────────────────────────────────

export type CheckCategory = "env" | "system" | "storage" | "ocr" | "routes" | "all";

/**
 * Run diagnostics checks.
 * @param categories - Which categories to run (default: all)
 * @param options.port - Port to check (default: 3000)
 */
export async function runDiagnostics(
  categories?: CheckCategory[],
  options?: { port?: number }
): Promise<DiagnosticReport> {
  const checks: { name: string; fn: () => Promise<DiagnosticResult>; category: CheckCategory }[] = [];

  const add = (name: string, fn: () => Promise<DiagnosticResult>, cat: CheckCategory) => {
    checks.push({ name, fn, category: cat });
  };

  add("Environment Variables", checkEnvVars, "env");
  add("Dependencies", checkDependencies, "system");
  add("Disk & Temp", checkDisk, "system");
  add("Port Availability", () => checkPort(options?.port ?? 3000), "system");
  add("MongoDB", checkMongoDB, "storage");
  add("OCR Pipeline", checkOCRPipeline, "ocr");
  add("Routes", checkRoutes, "routes");
  add("ErrorBoundary Component", checkErrorBoundary, "routes");

  const toRun = categories && !categories.includes("all")
    ? checks.filter((c) => categories.includes(c.category))
    : checks;

  // Run all checks in parallel where possible
  const results = await Promise.all(
    toRun.map((c) => check(c.name, c.fn))
  );

  const summary = {
    pass: results.filter((r) => r.status === "pass").length,
    fail: results.filter((r) => r.status === "fail").length,
    warn: results.filter((r) => r.status === "warn").length,
    skip: results.filter((r) => r.status === "skip").length,
    total: results.length,
  };

  return {
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || "development",
    summary,
    results,
  };
}

/**
 * Quick boot-time health check — runs critical checks only.
 * Logs warnings but does NOT throw — safe to call on server startup.
 */
export async function bootHealthCheck(): Promise<void> {
  const results = await runDiagnostics(["env", "ocr", "storage"]);

  for (const r of results.results) {
    if (r.status === "fail") {
      logger.error({ diagnostic: r.name, message: r.message, detail: r.detail });
    } else if (r.status === "warn") {
      logger.warn({ diagnostic: r.name, message: r.message });
    } else {
      logger.info({ diagnostic: r.name, message: r.message });
    }
  }

  if (results.summary.fail > 0) {
    logger.warn(`Boot diagnostics: ${results.summary.fail} failure(s) — app may have reduced functionality`);
  }
}

/**
 * Print a formatted report to stdout (for CLI use).
 */
export function formatReport(report: DiagnosticReport): string {
  const lines: string[] = [];
  const ICON = { pass: "✓", fail: "✗", warn: "!", skip: "—" } as const;

  lines.push(`\n  MenuLens Diagnostics Report`);
  lines.push(`  ${"=".repeat(42)}`);
  lines.push(`  Timestamp: ${report.timestamp}`);
  lines.push(`  Environment: ${report.environment}`);
  lines.push("");

  for (const r of report.results) {
    const icon = ICON[r.status] || "?";
    lines.push(`  ${icon}  ${r.name}`);
    lines.push(`     ${r.message}`);
    if (r.detail) {
      for (const line of r.detail.split("\n")) {
        lines.push(`     ${line}`);
      }
    }
    if (r.duration_ms !== undefined) {
      lines.push(`     (${r.duration_ms}ms)`);
    }
    lines.push("");
  }

  const { pass, fail, warn, skip } = report.summary;
  lines.push(`  ${"=".repeat(42)}`);
  lines.push(`  ${pass} passed, ${fail} failed, ${warn} warnings, ${skip} skipped`);

  if (fail > 0) {
    lines.push(`  ✗  ${fail} blocking issue(s) need attention`);
  }
  if (warn > 0) {
    lines.push(`  !  ${warn} non-blocking issue(s) to review`);
  }
  lines.push("");

  return lines.join("\n");
}
